// LoadCorrections loads the purchaseItem's Corrections into the .R struct
func (o *PurchaseItem) LoadCorrections(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Corrections = nil
	o.R.Loaded.Corrections = false

	related, err := o.Corrections(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.PurchaseItem = o
		rel.R.Loaded.PurchaseItem = true
	}

	o.R.Corrections = related
	o.R.Loaded.Corrections = true
	return nil
}

// LoadCorrections loads the purchaseItem's Corrections into the .R struct
func (os PurchaseItemSlice) LoadCorrections(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	corrections, err := os.Corrections(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Corrections = nil
		o.R.Loaded.Corrections = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range corrections {

			if !(o.PurchaseID == rel.PurchaseID) {
				continue
			}

			if !rel.ItemID.Valid {
				continue
			}
			if !(rel.ItemID.Valid && o.ID == rel.ItemID.V) {
				continue
			}

			rel.R.PurchaseItem = o
			rel.R.Loaded.PurchaseItem = true

			o.R.Corrections = append(o.R.Corrections, rel)
		}
	}

	return nil
}

